const platform = $json;
const now = new Date();
const dayMs = 24 * 60 * 60 * 1000;
const lastSuccess = platform.last_success_at
  ? new Date(platform.last_success_at)
  : null;
const isWeekly = lastSuccess && !Number.isNaN(lastSuccess.getTime());
const periodEnd = now;
const periodStart = isWeekly
  ? lastSuccess
  : new Date(now.getTime() - 30 * dayMs);

return {
  json: {
    ...platform,
    client_data: Array.isArray(platform.clients)
      ? platform.clients[0]
      : platform.clients,
    sync_type: isWeekly ? 'weekly' : 'initial_historical',
    period_start: periodStart.toISOString(),
    period_end: periodEnd.toISOString(),
    sync_platform: 'x'
  }
};

const username = String($json.username || '')
  .replace(/^@/, '')
  .trim();

if (!username) {
  throw new Error('اسم حساب X غير موجود');
}

const keywords = Array.isArray($json.settings?.keywords)
  ? $json.settings.keywords
  : [];

const searchParts = [`@${username}`];

for (const keyword of keywords) {
  const value = String(keyword || '').trim();

  if (value) {
    searchParts.push(`"${value}"`);
  }
}

const startDate = String($json.period_start).slice(0, 10);
const endDate = String($json.period_end).slice(0, 10);

const xQuery = [
  `(${searchParts.join(' OR ')})`,
  `-from:${username}`,
  '-filter:retweets',
  `since:${startDate}`,
  `until:${endDate}`
].join(' ');

return {
  json: {
    ...$json,
    x_query: xQuery,
    max_items:
      $json.sync_type === 'initial_historical'
        ? 1000
        : 200
  }
};

const platform = $('Build X Search Query').item.json;

const monitoredUsername = String(platform.username || '')
  .replace(/^@/, '')
  .trim()
  .toLowerCase();

const output = [];

for (const item of items) {
  const tweet = item.json;

  if (
    tweet.noResults === true ||
    tweet.type !== 'tweet' ||
    !tweet.id
  ) {
    continue;
  }

  const authorUsername = String(
    tweet.author?.userName || ''
  ).toLowerCase();

  // تجاهل منشورات حساب المنشأة نفسه
  if (
    monitoredUsername &&
    authorUsername === monitoredUsername
  ) {
    continue;
  }

  const mentionText =
    tweet.fullText ||
    tweet.text ||
    '';

  if (!mentionText.trim()) {
    continue;
  }

  let postedAt = null;

  if (tweet.createdAt) {
    const parsedDate = new Date(tweet.createdAt);

    if (!Number.isNaN(parsedDate.getTime())) {
      postedAt = parsedDate.toISOString();
    }
  }

  output.push({
    json: {
      client_id: platform.client_id,
      branch_id: platform.branch_id ?? null,
      platform_id: platform.id,

      tweet_id: String(tweet.id),
      author_username:
      tweet.author?.userName ||
      null,

    tweet_url:
      tweet.url ||
      tweet.twitterUrl ||
      null,
      mention_text: mentionText.trim(),
      posted_at: postedAt,

      public_metrics: {
        like_count: Number(tweet.likeCount || 0),
        reply_count: Number(tweet.replyCount || 0),
        retweet_count: Number(tweet.retweetCount || 0),
        quote_count: Number(tweet.quoteCount || 0),
        view_count: Number(tweet.viewCount || 0),
        bookmark_count: Number(tweet.bookmarkCount || 0)
      },

      analysis_status: 'pending',

      raw_data: {
        ...tweet,
        monitored_username: platform.username,
        client_platform_id: platform.id
      }
    }
  });
}

const fetchFailed = items.some(({ json }) =>
  Boolean(json?.error || json?.errorDescription || json?.requestErrorMessages)
);

if (output.length === 0) {
  return [{ json: {
    fetch_succeeded: !fetchFailed,
    has_mentions: false,
    client_id: platform.client_id,
    branch_id: platform.branch_id ?? null,
    platform_id: platform.id
  } }];
}

return output.map(({ json }) => ({
  json: { ...json, fetch_succeeded: true, has_mentions: true }
}));

const platform = $('Build X Search Query').first().json;

return [
  {
    json: {
      client_id: platform.client_id,
      branch_id: platform.branch_id ?? null,
      platform_id: platform.id
    }
  }
];

const platform = $('Continue X Platform').first().json;

const mentions = items
  .filter(item => item.json.id && item.json.mention_text)
  .map(item => ({
    // رقم السجل داخل جدول x_mentions
    source_record_id: item.json.id,

    // معرف التغريدة الأصلي من X
    tweet_id: item.json.tweet_id,

    author_username:
      item.json.author_username ||
      null,

    tweet_url:
      item.json.tweet_url ||
      null,

    mention_text:
      item.json.mention_text,

    posted_at:
      item.json.posted_at ||
      null,

    public_metrics:
      item.json.public_metrics ||
      {}
  }));

if (!mentions.length) {
  return [];
}

return [
  {
    json: {
      client_id: platform.client_id,
      branch_id: platform.branch_id ?? null,
      platform_id: platform.platform_id,

      platform_name: 'x',
      source_table: 'x_mentions',

      mentions
    }
  }
];

const aiItems = $input.all();

// غيّري اسم العقدة هنا إلى العقدة التي جلبت سجلات x_mentions
// قبل إرسالها إلى Analyze X Mentions
const sourceRows = $('Get Pending X Mentions')
  .all()
  .map(item => item.json);

const sourceMap = new Map(
  sourceRows.map(row => [String(row.id), row])
);

function toBoolean(value) {
  if (typeof value === 'boolean') return value;

  if (typeof value === 'string') {
    return ['true', '1', 'yes', 'نعم'].includes(
      value.trim().toLowerCase()
    );
  }

  return Boolean(value);
}

function getAIText(item) {
  return (
    item.json.output?.[0]?.content?.[0]?.text ??
    item.json.output_text ??
    item.json.text ??
    ''
  );
}

function parseJson(rawText) {
  if (!rawText) {
    throw new Error('نتيجة الذكاء الاصطناعي فارغة');
  }

  let cleaned = String(rawText)
    .trim()
    .replace(/^\uFEFF/, '')
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '');

  const objectStart = cleaned.indexOf('{');
  const arrayStart = cleaned.indexOf('[');

  let startIndex = -1;

  if (objectStart === -1) {
    startIndex = arrayStart;
  } else if (arrayStart === -1) {
    startIndex = objectStart;
  } else {
    startIndex = Math.min(objectStart, arrayStart);
  }

  const endIndex = Math.max(
    cleaned.lastIndexOf('}'),
    cleaned.lastIndexOf(']')
  );

  if (startIndex === -1 || endIndex === -1) {
    throw new Error('لم يتم العثور على JSON صالح في نتيجة الذكاء الاصطناعي');
  }

  cleaned = cleaned
    .slice(startIndex, endIndex + 1)
    .replace(/,\s*([}\]])/g, '$1');

  try {
    return JSON.parse(cleaned);
  } catch (error) {
    throw new Error(`JSON غير صالح: ${error.message}`);
  }
}

const outputItems = [];

for (const aiItem of aiItems) {
  const parsed = parseJson(getAIText(aiItem));

  const results = Array.isArray(parsed)
    ? parsed
    : Array.isArray(parsed.results)
      ? parsed.results
      : [];

  if (results.length === 0) {
    throw new Error('مصفوفة results غير موجودة أو فارغة');
  }

  for (const result of results) {
    const sourceRecordId =
      result.source_record_id ??
      result.id ??
      null;

    if (!sourceRecordId) {
      throw new Error('source_record_id غير موجود في نتيجة التحليل');
    }

    const source = sourceMap.get(String(sourceRecordId));

    if (!source) {
      throw new Error(
        `لم يتم العثور على منشور X رقم ${sourceRecordId}`
      );
    }

    outputItems.push({
      json: {
        client_id: source.client_id,
        branch_id: source.branch_id ?? null,
        platform_id: source.platform_id,
        platform_name: 'x',


        source_table: 'x_mentions',
        source_record_id: source.id,

        sentiment: result.sentiment ?? 'neutral',

        category: Array.isArray(result.category)
          ? result.category
          : result.category
            ? [result.category]
            : ['other'],

        severity: result.severity ?? 'low',

        needs_reply: toBoolean(result.needs_reply),

        is_sales_opportunity: toBoolean(
          result.is_sales_opportunity
        ),

        is_complaint: toBoolean(
          result.is_complaint
        ),

        suggested_reply: result.suggested_reply ?? null,
        reason: result.reason ?? null,
        analysis_summary: result.analysis_summary ?? null,

        analysis_status: 'completed',
        model_name: 'gpt-4o-mini',
        analyzed_at: new Date().toISOString()
      }
    });
  }
}

return outputItems;

const inputItems = $input.all();
const batchSize = 50;
const now = new Date().toISOString();

const rows = inputItems.map((item) => {
  const row = item.json;

  return {
    client_id: row.client_id,
    branch_id: row.branch_id ?? null,
    platform_id: row.platform_id,

    tweet_id: String(row.tweet_id),
    author_username: row.author_username ?? null,
    tweet_url: row.tweet_url ?? null,
    mention_text: row.mention_text ?? "",

    posted_at: row.posted_at,
    created_at: row.created_at ?? now,

    public_metrics: row.public_metrics ?? {},
    analysis_status: row.analysis_status ?? "pending",
    raw_data: row.raw_data ?? {},

    updated_at: row.updated_at ?? now
  };
});

const batches = [];

for (let i = 0; i < rows.length; i += batchSize) {
  batches.push({
    json: {
      rows: rows.slice(i, i + batchSize),
      batch_number: Math.floor(i / batchSize) + 1,
      total_batches: Math.ceil(rows.length / batchSize),
      total_rows: rows.length
    }
  });
}

return batches;
